// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

const collection = 'dr_uc05_reorder';
const collectionUrl = `${baseUrl}/admin/settings/data-model/${collection}`;

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(300000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);

    const pageErrors: Error[] = [];
    page.on('pageerror', (err) => pageErrors.push(err));

    const reorderPatchStatuses: number[] = [];
    page.on('response', (response) => {
        if (response.url().includes(`/fields/${collection}`) && response.request().method() === 'PATCH') {
            reorderPatchStatuses.push(response.status());
        }
    });

    // Deterministic baseline: the collection, its fields, and their sort order.
    const setupLogin = await page.request.post(`${baseUrl}/auth/login`, {
        data: { email: 'admin@example.com', password: 'admin' },
    });
    expect(setupLogin.status()).toBe(200);
    const adminToken = (await setupLogin.json()).data.access_token;
    const authHeaders = { Authorization: `Bearer ${adminToken}` };

    const collectionProbe = await page.request.get(`${baseUrl}/collections/${collection}`, { headers: authHeaders });
    if (collectionProbe.status() !== 200) {
        await page.request.post(`${baseUrl}/collections`, {
            headers: authHeaders,
            data: { collection, meta: { icon: 'drag_indicator' }, schema: {} },
        });
        for (const field of ['alpha', 'bravo', 'charlie']) {
            await page.request.post(`${baseUrl}/fields/${collection}`, {
                headers: authHeaders,
                data: { field, type: 'string', meta: { interface: 'input' }, schema: {} },
            });
        }
    }
    const baselineReset = await page.request.patch(`${baseUrl}/fields/${collection}`, {
        headers: authHeaders,
        data: [
            { field: 'id', meta: { sort: 1, group: null } },
            { field: 'alpha', meta: { sort: 2, group: null } },
            { field: 'bravo', meta: { sort: 3, group: null } },
            { field: 'charlie', meta: { sort: 4, group: null } },
        ],
    });
    expect(baselineReset.status()).toBe(200);

    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(collectionUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    await page.getByRole("textbox", { name: "Email" }).fill(getValue(playwrightRequest0, "email"));
    await page.getByRole("textbox", { name: "Password" }).fill(getValue(playwrightRequest0, "password"));
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise0 = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    const response0 = await responsePromise0;
    expect(response0.status()).toBe(200);

    await page.waitForLoadState('networkidle');

    const remindLater = page.getByRole("button", { name: "Remind Later" });
    if (await remindLater.isVisible().catch(() => false)) {
        await remindLater.click();
    }

    const fieldRows = page.locator('.field-grid .field-select');
    const fieldNames = page.locator('.field-grid .field-select .name');
    const dragHandles = page.locator('.field-grid .field-select .drag-handle');
    await fieldNames.first().waitFor({ state: 'visible', timeout: 20000 });

    await expect(fieldNames).toHaveCount(4);
    await expect(fieldNames.nth(1)).toHaveText('alpha');
    await expect(fieldNames.nth(2)).toHaveText('bravo');
    await expect(fieldNames.nth(3)).toHaveText('charlie');

    // Cancelled drag: press the "alpha" handle and release it back inside its own slot.
    // @end fires without @update:model-value, so no reorder save may be issued.
    const cancelledHandle = (await dragHandles.nth(1).boundingBox())!;
    await page.mouse.move(cancelledHandle.x + cancelledHandle.width / 2, cancelledHandle.y + cancelledHandle.height / 2);
    await page.mouse.down();
    await page.mouse.move(cancelledHandle.x + cancelledHandle.width / 2, cancelledHandle.y + cancelledHandle.height / 2 + 15, { steps: 10 });
    await page.mouse.up();
    await page.waitForTimeout(2000);

    // The order is untouched, no save was sent, and the drag lifecycle left no residue.
    await expect(fieldNames).toHaveCount(4);
    await expect(fieldNames.nth(1)).toHaveText('alpha');
    await expect(fieldNames.nth(2)).toHaveText('bravo');
    await expect(fieldNames.nth(3)).toHaveText('charlie');
    await expect(page.locator('.field-grid .field-select[data-dragging]')).toHaveCount(0);
    await expect(page.locator('.field-grid .field-select[data-saving]')).toHaveCount(0);
    expect(reorderPatchStatuses).toHaveLength(0);

    // A real drag after the cancelled one still reorders and still saves.
    const sourceHandle = (await dragHandles.nth(2).boundingBox())!;
    const dropTarget = (await fieldRows.nth(3).boundingBox())!;
    await page.mouse.move(sourceHandle.x + sourceHandle.width / 2, sourceHandle.y + sourceHandle.height / 2);
    await page.mouse.down();
    await page.mouse.move(sourceHandle.x + sourceHandle.width / 2, dropTarget.y + dropTarget.height * 0.75, { steps: 25 });
    const reorderPatchPromise = page.waitForResponse(
        (response) => response.url().includes(`/fields/${collection}`) && response.request().method() === 'PATCH',
    );
    await page.mouse.up();
    const reorderPatch = await reorderPatchPromise;
    expect(reorderPatch.status()).toBe(200);
    expect(reorderPatchStatuses).toHaveLength(1);
    const reorderPatchBody = await reorderPatch.json();
    expect(reorderPatchBody.data).toHaveLength(4);
    expect(Object.fromEntries(reorderPatchBody.data.map((field: any) => [field.field, field.meta.sort])))
        .toEqual({ id: 1, alpha: 2, charlie: 3, bravo: 4 });

    await expect(fieldNames).toHaveCount(4);
    await expect(fieldNames.nth(1)).toHaveText('alpha');
    await expect(fieldNames.nth(2)).toHaveText('charlie');
    await expect(fieldNames.nth(3)).toHaveText('bravo');
    await expect(page.locator('.field-grid .field-select[data-saving]')).toHaveCount(0);

    // Reload: only the second drag was persisted.
    await page.goto(collectionUrl);
    await page.waitForLoadState('networkidle');
    await fieldNames.first().waitFor({ state: 'visible', timeout: 20000 });
    await expect(fieldNames).toHaveCount(4);
    await expect(fieldNames.nth(0)).toHaveText('id');
    await expect(fieldNames.nth(1)).toHaveText('alpha');
    await expect(fieldNames.nth(2)).toHaveText('charlie');
    await expect(fieldNames.nth(3)).toHaveText('bravo');

    expect(pageErrors).toHaveLength(0);
});
